if api_host not in aliases:raise SystemExit('API database host does not identify selected database container')
def running_peers():
 ids=run(['docker','ps','-q']).decode().split()
 if not ids:return []
 return [c for c in json.loads(run(['docker','inspect',*ids])) if any(x.get('Source')==mount['Source'] for x in c['Mounts'])]

def helper(script,payload=None):
 return run(['docker','run','--rm','-i','--network','none','--user','0','--volumes-from',a.api,'--entrypoint','sh',db['Image'],'-c',script,'maintenance',root,marker],payload)
def read_marker():return helper('set -eu; test ! -L "$1"; test ! -L "$2"; cat "$2"')
if a.action=='status':
 m=json.loads(read_marker());print(json.dumps({'held':True,'operationId':m['operationId'],'candidate':m['candidate']}));raise SystemExit(0)
# Keep psql stdin open for the whole filesystem operation. No credentials leave the DB container.
