            {
                Id = before.IngredientLines[0].Id, Description = "oil", Amount = LegacyGroceryQuantity.Parse("2"), AmountText = "2",
                Unit = new("tbsp", null), Scaling = "proportional", Shopping = new("oil", null, null)
            };
